class Solution {
public:
    string minInteger(string num, int k) {
        int n = num.size();
        long long K = k;
        vector<vector<int>> pos(10);
        for (int i = 0; i < n; i++) pos[num[i] - '0'].push_back(i);
        vector<int> bit(n + 1, 0);
        auto upd = [&](int i) { for (; i <= n; i += i & (-i)) bit[i]++; };
        auto qry = [&](int i) { int s = 0; for (; i > 0; i -= i & (-i)) s += bit[i]; return s; };
        string res;
        res.reserve(n);
        for (int step = 0; step < n; step++) {
            for (int d = 0; d < 10; d++) {
                if (pos[d].empty()) continue;
                int p = pos[d].front();
                long long cost = p - qry(p);
                if (cost <= K) {
                    K -= cost;
                    pos[d].erase(pos[d].begin());
                    upd(p + 1);
                    res += char('0' + d);
                    break;
                }
            }
        }
        return res;
    }
};
